(()=>{"use strict";let t=self;t.addEventListener("push",i=>{if(!i.data)return;let n=i.data.json();i.waitUntil(t.registration.showNotification(n.title,{body:n.body,icon:n.icon??"/images/icon-192x192.png",badge:"/images/icon-192x192.png",data:{url:n.url??"/"}}))}),t.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data?.url??"/";i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{let e=i.find(t=>t.url===n&&"focus"in t);return e?e.focus():t.clients.openWindow(n)}))})})();